    summary: "Aprende sobre uma área usando sistemas de raízes.",
    description: "Você obtém insights gerais sobre a vizinhança imediata, enviando seus sentidos através do sistema radicular de árvores e arbustos. Se houver criaturas médias ou maiores despercebidas na área, você fica sabendo da presença delas e elas são indetectadas por você. Você pode tentar imediatamente Procurar uma criatura indetectada e ganha +1 de bônus de status para esta tentativa e qualquer uma de suas outras tentativas de Procurar criaturas escondidas ou indetectadas até o fim do seu próximo turno. Você também aprende se alguma dessas criaturas passou por esta área na última hora, embora você obtenha apenas uma vaga noção de direção da magia. Se você começar a Rastrear uma criatura detectada desta forma, você ganha +1 de bônus de status no teste inicial.",
