    provenance: { type: 'official' },
    actionType: "two",
    summary: "Corta criaturas com ondulações de ar.",
    description: "Você corta o ar com a mão, canalizando ondas de ar em miniatura de cada dedo para cortar seu inimigo. Se você tiver duas mãos livres, você pode atingir duas criaturas com esta magia; caso contrário, você terá como alvo um.\n\n Faça uma rolagem de ataque de magia contra o CA de cada alvo. Isso causa 2d4 dano cortante. Sucesso crítico: um alvo também leva 1d4 dano persistente de sangramento. Se você estiver atacando duas criaturas, isso conta como dois ataques para seu ataque de ataques múltiplos, mas a penalidade não aumenta até depois de ambos os ataques.\n\n**Sucesso crítico** O alvo sofre dano duplo e 1d4 dano persistente de sangramento.\n\n**Sucesso** O alvo sofre dano total.\n\n**Altura (+1)** O dano aumenta em 1d4, e o dano persistente em um acerto crítico aumenta em 1d4.",
