    rarity: "common",
    provenance: { type: 'official' },
    actionType: "one",
    summary: "Puxa um fôlego extraordinariamente fundo.",
    description: "Você respira incrivelmente fundo e pode prendê-lo durante a duração da magia. Você não perde o fôlego ao ser atingido, mas perde todo o ar que inalou se falar (inclusive para Conjurar uma Magia). Este magia não cria ar; se você não tiver ar para respirar ao lançá-lo, não obterá nenhum benefício.\n\n**Altura (2º)** A duração aumenta para 1 hora, e você perde apenas 10 minutos de fôlego se falar.\n\n**Altura (4º)** A duração aumenta para 8 horas, e você perde apenas 10 minutos de fôlego se falar.",
