    summary: "Ao conjurar, você ganha um senso perfeito do tempo.",
    description: "Ao lançar a magia, você ganha uma noção perfeita do tempo. Você pode saber exatamente que horas são, até o segundo. Em vez disso, você pode optar por obter uma noção perfeita do calendário se tiver conhecimento nessa área – se você for treinado em Natureza, poderá saber exatamente quanto tempo falta para o nascer do sol e quantos dias até o próximo solstício. Se você for treinado em conhecimento astronômico, poderá aprender com precisão quando qualquer conjunção astronômica previsível conhecida começará e terminará, e assim por diante.\n\n Você pode ganhar um bônus de status de +1 para uma rolagem de ataque, verificação de Percepção, salvaguardas ou teste de perícia que você realiza no mesmo turno em que lança _Sentido do Tempo_ que requer um tempo extremamente preciso. Se você optar por ganhar esse bônus, não poderá ganhá-lo novamente por 1 hora.",
