    summary: "Envia uma frase através da pedra.",
    description: "Você envia uma série de tremores, não mais do que uma frase curta, em direção ao seu alvo. Se o alvo estiver dentro do alcance e conectado ao mesmo corpo terrestre que você, as vibrações atingirão o alvo através do solo. Você não precisa de linha de visão nem de linha de efeito, então um alvo em outro andar de um edifício é um alvo válido.\n\n O alvo pode dar uma breve resposta vibracional como reação ou como uma ação livre em seu próximo turno, mas ele deve estar dentro do alcance para fazê-lo. Se eles responderem, a resposta deles será entregue a você por meio de tremores que você sente, como acontece com a mensagem original. Os tremores transmitem um significado claro somente se você e o alvo conhecerem esse significado, como três tremores para um aviso específico e dois para outro. Nenhum de vocês pode transmitir um significado novo ou matizado usando esta magia.\n\n Uma criatura que tenha sentido sísmico pode sentir as vibrações desta magia se a criatura estiver dentro do alcance das vibrações em qualquer ponto durante sua jornada até qualquer alvo.\n\n**Altura (4º)** A magia pode atingir até 5 criaturas.",
