    summary: "Coleta informação ao redor e guarda em forma de livro numa dimensão de bolso. (raro) Altura 3º, 6º, 9º.",
    description: "Como Vil Seral, você coleta informações ao seu redor e as armazena em forma de livro em uma biblioteca extradimensional. Ao Conjurar esta Magia, escolha qualquer habilidade na qual você seja pelo menos treinado e que tenha a ação Recordar Conhecimento.\n\n Durante a duração desta magia, você pode invocar um tomo da biblioteca extradimensional ao tentar um teste de Recordar Conhecimento usando a habilidade escolhida. Isso faz parte da ação da Recordar Conhecimento. Você deve ter uma mão livre para fazer isso. O tomo aparece em sua mão, aberto na página apropriada. Isso concede a você um bônus de status de +1 no teste Recordar Conhecimento. Se você obtiver uma falha crítica neste teste, você obterá uma falha. Se o teste for bem-sucedido e o alvo for uma criatura, você ganha informações adicionais ou contexto sobre a criatura. Depois de fazer referência a um livro do seu _Biblioteca de Bolso_, a magia termina.\n\n**Altura (3º)** O bônus de status aumenta para +2 e você pode referenciar seu _Biblioteca de Bolso_ duas vezes antes da magia terminar.\n\n**Altura (6º)** O bônus de status aumenta para +3 e você pode referenciar seu _Biblioteca de Bolso_ três vezes antes da magia terminar.\n\n**Altura (9º)** O bônus de status aumenta para +4 e você pode referenciar seu _Biblioteca de Bolso_ quatro vezes antes da magia terminar.",
