    description: "Você lança um jato de água salgada com a mão estendida. Faça um ataque de magia à distância contra um alvo dentro do alcance.\n\n**Sucesso crítico** A criatura sofre 4d6 dano de concussão e fica cega por 1 rodada e ofuscada por 1 minuto enquanto água salgada espirra em seus olhos. A criatura pode gastar uma ação Interagir para esfregar os olhos e acabar com a condição cego, mas não com a condição ofuscado.\n\n**Sucesso** A criatura sofre 2d6 dano de concussão e fica cega por 1 rodada. A criatura pode gastar uma ação Interagir limpando a água salgada dos olhos para acabar com a condição cega.\n\n**Altura (+1)** O dano aumenta em 2d6.",
