    provenance: { type: 'official' },
    actionType: "two",
    summary: "Faz a criatura repetir a mesma ação.",
    description: "Você coloca um processo de pensamento na mente do alvo, forçando-o a repetir ações de um momento. O alvo deve tentar uma salvaguarda de Vontade. Se o alvo falhar, quaisquer ações que o alvo usar no próximo turno, ele deverá repetir no turno seguinte. As ações devem ser repetidas na mesma ordem e o mais próximo possível das mesmas especificidades. Por exemplo, se o alvo fizer um ataque, ele deverá repetir o ataque contra a mesma criatura, se possível, e se o alvo se mover, ele deverá se mover na mesma distância e direção, se possível, no seu próximo turno.\n\n Se o alvo não puder repetir uma ação, como Conjurar um Magia que foi esgotado ou precisar atingir uma criatura que morreu, ele poderá agir como quiser para essa ação, mas se tornará aturdido 1 até o final do seu turno.",
