    provenance: { type: 'official' },
    actionType: "two",
    summary: "Deixa criaturas ressecadas: dano e enfraquecimento. Altura +2.",
    description: "Você atiça o fogo interno de todas as coisas da área, expulsando a umidade. Todas as criaturas na área recebem 1d6 dano persistente de fogo com uma salvaguarda básica de Fortitude; criaturas com características de água ou planta obtêm um resultado um grau de sucesso pior do que o obtido. A magia termina para uma criatura quando seu dano persistente termina.\n\n Uma criatura afetada por _Desidratar_ tenta uma salvaguarda de Fortitude adicional no final de cada um de seus turnos, antes de rolar para se recuperar do dano persistente. Ele pode renunciar a esse salvamento adicional se tiver consumido água ou um líquido hidratante semelhante na última rodada (beber normalmente requer 1 ação).\n\n**Sucesso** A criatura não sofre nenhum efeito adicional.\n\n**Falha** A criatura fica enfraquecido 1 até o final do seu próximo turno.\n\n**Falha crítica** A criatura fica enfraquecido 2 até o final do seu próximo turno.\n\n**Altura (+2)** O alcance aumenta em 3 m, a explosão aumenta em 1,5 m e o dano persistente de fogo aumenta em 3d6.",
