    traditions: ["arcane", "occult"],
    traits: ["Concentrate", "Illusion", "Manipulate"],
    rarity: "common",
    provenance: { type: 'official' },
    summary: "Mascara a aura de uma magia ou item. (1 min) Altura 2º.",
    description: "Você altera a aparência da aura mágica de um item ou magia para efeitos como _Detectar Magia_. Você pode ocultar as auras completamente, ter um item registrado como um item comum de nível inferior ou fazer um registro de magia como uma magia comum de mesmo nível ou inferior. Você pode descartar a magia.\n\n Um conjurador usando _Detectar Magia_ ou _Ler Aura_ de classificação superior a _Disfarçar Magia_ pode tentar desacreditar a ilusão usando a habilidade que corresponde à tradição da magia (Arcanismo para arcano, Religião para divino, Ocultismo para ocultismo ou Natureza para primitivo). Outras tentativas do mesmo conjurador obtêm o mesmo resultado do teste inicial de descrença.\n\n**Altura (2º)** Você pode Conjurar esta Magia em uma criatura, disfarçando todos os itens e efeitos de magia nela.",
