    rarity: "uncommon",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Trapaceia em jogos de azar. (incomum) Altura 5º.",
    description: "Você se concede uma sorte sobrenatural em cartas, dados e outros jogos de azar. Você ganha um bônus de status de +1 em testes de Conhecimento de Jogos para jogar, e se você obtiver uma falha crítica em tal teste, você receberá uma falha; no entanto, a magia tem vida muito curta para ser usado em testes de Ganhar Renda com jogos de azar. Quando você está sob o efeito de _nudge the odds_, uma característica facial, como uma mecha de cabelo ou a íris de um olho, se transforma em uma cor dourada distinta; o Mestre escolhe qual recurso quando você lança a magia. Esta mudança resiste a todos os esforços mágicos para ocultá-la, embora possa ser escondida ou encoberta por meios mundanos. Uma criatura que perceba o recurso pode identificar a magia usando Recordar Conhecimento. Por evitar grandes perdas, os jogadores consideram _nudge the odds_ uma forma repugnante de trapaça. Se você for pego usando a magia, provavelmente sofrerá sérias consequências dependendo da natureza dos jogadores que você enganou.\n\n**Altura (5º)** O bônus de status aumenta para +2, e a duração aumenta para durar até a próxima vez que você fizer seus preparativos diários. Se você continuar gastando seu espaço de magia todos os dias para manter a duração ativa, isso permitirá que você aplique o efeito a uma verificação de tempo de inatividade para Ganhar Renda.",
