    actionType: "two",
    summary: "Uma criatura fica mais amistosa com você. Altura 4º, 8º.",
    description: "Para o alvo, suas palavras são mel e seu rosto parece banhado por uma névoa sonhadora. Ele deve tentar uma salvaguarda de Vontade, com +4 bônus de circunstância se você ou seus aliados o ameaçaram recentemente ou usaram ações hostis contra ele.\n\n Você pode descartar a magia. Se você usar ações hostis contra o alvo, a magia termina. Quando a magia termina, o alvo não necessariamente percebe que foi encantado, a menos que sua amizade com você ou as ações que você o convenceu a tomar entrem em conflito com suas expectativas, o que significa que você poderia potencialmente convencer o alvo a continuar sendo seu amigo por meios mundanos.\n\n**Sucesso crítico** O alvo não é afetado e sabe que você tentou encantá-lo.\n\n**Sucesso** O alvo não é afetado, mas pensa que seu magia foi algo inofensivo em vez de _Encantar_, a menos que identifique a magia.\n\n**Falha** A atitude do alvo se torna amigável com você. Se foi amigável, torna-se útil. Não pode usar ações hostis contra você.\n\n**Falha crítica** A atitude do alvo torna-se útil para você e ele não pode usar ações hostis contra você.\n\n**Altura (4º)** A duração dura até seus próximos horários diários.\n\n**Altura (8º)** A duração dura até suas próximas diárias, e você pode atingir até 10 criaturas.",
