    summary: "Esconde familiar ou companheiro numa dimensão de bolso.",
    description: "Você abre sua capa ou cria um espaço com as mãos, desenhando o alvo em uma dimensão de bolso grande o suficiente para seu conforto básico. Nenhuma outra criatura pode entrar neste espaço extradimensional, e o alvo só pode trazer objetos se eles forem projetados para serem usados ​​por uma criatura de sua espécie. O espaço tem ar, comida e água suficientes para sustentar o alvo durante todo o período.\n\n Você pode descartar a magia. A magia também termina se você morrer ou entrar em um espaço extradimensional. Quando a magia termina, o alvo reaparece no espaço desocupado mais próximo (fora de qualquer espaço extradimensional em que você possa ter entrado).",
