    description: "Você reúne energia mágica na palma da mão, formando uma bola concentrada de eletricidade que estala e ressoa como um trovão impossivelmente distante. Faça uma rolagem de ataque de magia à distância contra o CA do seu alvo. Sucesso: you deal 3d6 dano de eletricidade. Sucesso crítico: o alvo sofre o dobro de dano e fica ofuscado por 1 rodada. O número de ações que você gasta ao Conjurar esta Magia determina seu alcance, bem como outros parâmetros.\n\n**2 ações** Este magia tem alcance de 9 m.\n **3 ações** Este magia tem um alcance de 18 m e causa metade do dano em caso de falha (mas não uma falha crítica) enquanto a eletricidade ataca e sacode o alvo.\n\n**Duas Rodadas** Se você gastar 3 ações Conjurando o Magia, você pode evitar terminar a magia e gastar mais 2 ações em seu próximo turno para fortalecer ainda mais a magia. Você pode realizar outras ações antes de terminar esta magia, mas a magia será perdida se você lançar outra magia entre elas. Após atacar o alvo, acertando ou errando, a bola de raio explode, causando 2d6 dano de eletricidade a todas as outras criaturas em uma emanação de 3 m ao redor do alvo (salvaguarda básica de Reflexos). Além disso, você acende eletricidade por 1 minuto, causando 1 dano de eletricidade a criaturas que lhe Agarrar ou que o atingiram com um Golpe desarmado ou uma arma corpo a corpo sem alcance.\n\n**Altura (+1)** O dano inicial em um acerto, bem como o dano de explosão para o tempo de lançamento de 2 rodadas, aumentam em 2d6 cada um, e o dano que as criaturas sofrem se Agarrar ou acertarem você enquanto você estiver em seu estado de faísca aumenta em 1.",
