    summary: "Puxa um arco-íris para ligar este mundo a outro. (raro) Altura +2.",
    description: "Você estende a mão para derrubar um arco-íris e aproveitar seu poder para conectar este mundo aos céus. Cada criatura na área sofre 1d4 dano espiritual com uma salvaguarda básica de Fortitude. Qualquer criatura que falhar neste teste será ofuscada adicionalmente por 1 rodada. Durante a duração da magia, um aliado adjacente a você pode interagir e ser instantaneamente teletransportado para um espaço desocupado na área da magia, desde que não viaje mais de 18 m. Este efeito tem a característica de teletransporte.\n\n**Altura (+2)** O dano aumenta em 2d4, a duração da condição ofuscado em caso de falha no salvamento aumenta em 1 rodada e a distância máxima que um aliado pode usar o arco-íris para se teletransportar aumenta em 3 m.",
