    description: "As plantas crescem rapidamente do solo. Todas as criaturas na área alvo sofrem 2d4 de dano. O tipo de dano depende do tipo de planta que você escolhe cultivar. Falha crítica: os alvos experimentam efeitos adicionais, também dependendo do que você escolhe cultivar. O tipo de planta e seus efeitos são escolhidos quando você lança a magia.\n\n- **Cactos** Dano perfurante e 1 dano persistente de sangramento em uma falha crítica.\n- **Flores** Dano de veneno e ofuscado por 2 rodadas em caso de falha crítica.\n- **Frutas** Dano de concussão e desajeitado 1 por 2 rodadas em caso de falha crítica.\n- **Raízes** Dano de concussão e as criaturas afetadas caem caídas em caso de falha crítica.\n\n**Altura (+1)** O dano aumenta em 1d4, e o dano persistente de sangramento dos cactos aumenta em 1.",
