    provenance: { type: 'official' },
    actionType: "three",
    summary: "Dispara um foguete explosivo para o céu. Altura +1.",
    description: "Com uma pitada de pólvora metálica e pólvora, você evoca uma energia vermelha escaldante que dispara direto para o ar e explode, desencadeando um estrondo crepitante. Com o tempo, você pode até personalizar seu próprio padrão e cor para o foguete à medida que refina a magia.\n\n Você não pode mudar a direção ou a distância do foguete – ele deve subir em linha reta, continuando até o alcance máximo, se possível. Se o foguete explodir em sua altura máxima, a luz brilhante poderá ser vista a até 16 quilômetros de distância e o som da explosão poderá ser ouvido a até 1,6 km de distância em condições climáticas claras.\n\n Se o foguete explodir em um espaço fechado menor que o tamanho total da explosão, cada criatura na área sofre 1d10 dano sônico dependendo do resultado de sua salvaguarda de Reflexos.\n\n**Sucesso crítico** A criatura não é afetada.\n\n**Sucesso** A criatura sofre metade do dano.\n\n**Falha** A criatura sofre dano total e fica ofuscada por 1 rodada.\n\n**Falha crítica** A criatura sofre o dobro de dano e fica cega por 1 rodada.\n\n**Altura (+1)** O dano sônico aumenta em 1d10.",
