    summary: "Cobre um alvo ou área com graxa escorregadia.",
    description: "Você conjura graxa, escolhendo uma área ou alvo.\n **Área** Todo o solo sólido da área está coberto com graxa. Cada criatura que estiver na superfície gordurosa deve ser bem sucedida em um teste de Salvaguarda de Reflexos ou Acrobacia contra seu CD de magia ou cairá caída. Criaturas usando uma ação para se mover para a superfície gordurosa durante a duração da magia devem tentar um teste de Salvaguarda de Reflexos ou um teste de Acrobacia para Equilibrar-se. Uma criatura que Anda ou Rasteja não precisa tentar um teste ou um teste de resistência. **Alvo** Se você lançar a magia em um objeto abandonado, qualquer um que tentar pegar o objeto deverá ter sucesso em um teste de Acrobacia ou salvaguarda de Reflexos contra seu CD de magia para fazê-lo. Se você mirar em um objeto assistido, a criatura que possui o objeto deve tentar um teste de Acrobacia ou Salvaguarda de Reflexos. Falha: o portador ou portador sofre -2 de coincidência de circunstância em todos os testes que envolvam o uso do objeto; em caso de falha crítica, o portador ou portador libera o item. O objeto cai em um quadrado adjacente à escolha do Mestre. Se você Conjurar esta Magia em um objeto desgastado, o usuário ganha +2 de bônus de circunstância para salvaguarda de Fortitudes contra tentativas de agarrá-los.",
