    summary: "Cria objetos de barro. Altura 2º, 3º.",
    description: "Você retira o material de barro do ambiente e, em seguida, molda-o em um ou mais objetos de barro que, em combinação, podem ser leves. Alternativamente, você pode lançar esta magia em objetos previamente criados com esta magia, estendendo sua duração. Nenhum objeto pode ter uma arte complexa ou peças móveis complexas, pode cumprir um custo ou algo semelhante, ou é feito de algo mais do que argila ou terra. Cada objeto é obviamente produto de magia temporária e, portanto, não pode ser vendido ou passado como um item valioso.\n\n**Altura (2º)** Você pode criar objetos de até 1 Bulk. Eles duram 8 horas.\n\n**Altura (3º)** Você pode criar objetos de até 2 Bulk. Eles duram 24 horas.",
