    rarity: "common",
    provenance: { type: 'official' },
    actionType: "three",
    summary: "Ordena automaticamente muitos objetos. Altura 3º.",
    description: "Você classifica magicamente um grupo de objetos em pilhas ou pilhas organizadas. Você pode classificar os objetos de duas maneiras diferentes. A primeira opção é separá-los em pilhas diferentes dependendo de um fator facilmente observável, como cor ou formato. Alternativamente, você pode classificar os objetos em pilhas ordenadas dependendo de uma notação claramente indicada, como número de página, título ou data. Os objetos se classificam sozinhos ao longo da duração, embora leve menos tempo por objeto para classificar um número menor de objetos, até uma única rodada para 30 ou menos objetos.\n\n**Altura (3º)** A magia pode separar até 500 objetos em um minuto, ou 75 objetos em uma rodada.",
