    description: "O mecanismo de trava do alvo se fecha, mantido firmemente por proteções mágicas invisíveis. Quando você trava magicamente um alvo, você define uma CD de Atletismo e Prestidigitação para abri-lo igual ao seu CD de magia ou a CD de bloqueio base com um bônus de status de +4, o que for maior. Qualquer chave ou combinação que uma vez abriu uma fechadura afetada por esta magia não o faz durante a duração da magia, embora a chave ou combinação conceda +4 de bônus de circunstância aos testes para abrir a porta.\n\n Se o alvo for aberto, a magia termina. Supondo que o alvo não esteja barrado ou travado de alguma forma adicional, você pode destravá-lo e abri-lo com uma ação Interagir durante a qual você toca o alvo. Isso não encerra a magia. Você pode Dispensar esta magia a qualquer momento e de qualquer distância.\n\n**Altura (2º)** A duração é ilimitada, mas você deve gastar 6 PO em metais preciosos como custo adicional.",
