    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Cria uma arma feita de fogo. Altura 4º, 6º, 8º, 10º.",
    description: "Contanto que você tenha magia, você nunca estará desarmado. Você materializa um simulacro flamejante de qualquer arma simples ou marcial comum nas mãos do alvo. O alvo deve ter a mão livre para segurar a arma, caso contrário a arma cairá no chão no espaço do alvo. A arma flamejante funciona como uma arma _+1 striking_ e seu tipo de dano muda para fogo. O tipo de dano não pode ser alterado usando a característica versátil, característica modular ou métodos semelhantes.\n\nUma arma lançada se rematerializa na mão do alvo após a conclusão do Golpe. Se você escolher uma arma de longo alcance que use munição, o usuário ainda deverá recarregar a arma usando o número normal de ações, embora isso gere munição automaticamente; funciona como munição normal e o _blazing weapon_ não pode usar outros tipos de munição.\n\n Qualquer criatura que não seja você ou o alvo que tentar tocar, fazer um Golpe ou Desarmar a arma sofre 1d6 dano de fogo a cada vez.\n\n**Altura (4º)** Você pode mirar em até 5 criaturas interessadas e pode escolher uma arma diferente para cada alvo. As armas funcionam como armas _+1 striking flaming_.\n\n**Altura (6º)** Como 4º, mas as armas funcionam como armas _+2 greater striking flaming_.\n\n**Altura (8º)** Como 4º, mas as armas funcionam como armas _+3 greater striking greater flaming_.\n\n**Altura (10º)** Como 4º, mas as armas funcionam como armas _+3 superior striking greater flaming_.",
