    summary: "Fogo conjurado se move a seu comando. Altura +1.",
    description: "Você cria um fogo que queima sem combustível e se move de acordo com seus comandos. A chama causa 3d6 dano de fogo a cada criatura no quadrado em que aparece, com uma salvaguarda básica de Reflexos. Ao sustentar esta magia, você pode levitar a chama até 3 m. Em seguida, ele causa dano a cada criatura cujo espaço compartilhou em qualquer ponto durante seu voo. Isso usa o mesmo dano e salvamento, e você rola o dano uma vez cada vez que Sustentar. Uma determinada criatura pode sofrer dano de _Chama Flutuante_ apenas 1 vez por rodada.\n\n**Altura (+1)** O dano aumenta em 1d6.",
    duration: "sustentada até 1 minuto",
    defense: "Reflexos",
    area: "1 quadrado de 1,5 m",
    range: "9 m",
    aonUrl: "https://2e.aonprd.com/Spells.aspx?ID=1533",
