    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Remove terra solta, poeira, cascalho ou areia (não pedra sólida). Altura +2.",
    description: "Você remove sujeira solta, poeira, cascalho, areia e similares (embora não seja pedra sólida) até o tamanho de um cubo de 1,5 m. Qualquer criatura Média ou menor que esteja no topo da terra quando a magia for lançada deve tentar um teste de Salvaguarda de Reflexos ou Acrobacia.\n\n**Sucesso** A criatura não é afetada e pode optar por descer do poço sem danos ou mover-se para o espaço disponível mais próximo de sua escolha.\n\n**Falha** A criatura cai caída no espaço disponível mais próximo à sua escolha ou cai no buraco se preferir.\n\n**Falha crítica** A criatura cai no poço escavado pelo magia e cai caída, sofrendo dano de queda normalmente.\n\n**Altura (+2)** A magia pode escavar um cubo adicional de 1,5 m de terra. Se você escavar todos os quatro cubos de 1,5 m abaixo de uma criatura Grande, ela deverá tentar um teste de salvaguarda de Reflexos ou Acrobacia, como acima.",
