    traits: ["Concentrate", "Manipulate"],
    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Levita o escudo tocado e o faz orbitar uma criatura. Altura 4º.",
    description: "Você levita o escudo tocado e o envia para orbitar uma criatura. Quando você lança a magia e o sustenta, o escudo usa a ação Erguer o Escudo para proteger a criatura alvo.\n\n**Altura (4º)** Se você tiver a reação Bloquear com o Escudo, você pode usar sua reação para fazer com que o escudo alvo use Bloquear com o Escudo quando a criatura alvo sofreria dano de um ataque físico, além do gatilho usual. Neste caso, Bloquear com o Escudo protege a criatura alvo, e não você. Como o escudo está usando Bloquear com o Escudo e não você, efeitos ou habilidades adicionais que normalmente se aplicam quando você Bloquear com o Escudo não se aplicam.",
