    description: "Você entorpece a mente do alvo, dependendo da sua salvaguarda de Vontade.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** A meta é aturdido 1 até o início do seu próximo turno.\n\n**Falha** O alvo é aturdido 2 por 1 minuto.\n\n**Falha crítica** O alvo é aturdido 3 por 1 minuto.",
