    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Estrondo causa dano e pode ensurdecer. Altura +1.",
    description: "Um ruído cacofônico explode, causando 2d10 dano sônico. Cada criatura deve tentar uma salvaguarda de Fortitude.\n\n**Sucesso crítico** A criatura não é afetada.\n\n**Sucesso** A criatura sofre metade do dano.\n\n**Falha** A criatura sofre dano total e fica surda por 1 rodada.\n\n**Falha crítica** A criatura sofre o dobro de dano e fica surdo por 1 minuto, e atordoado 1.\n\n**Altura (+1)** O dano aumenta em 1d10.",
