    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Faiscas queimam quem você golpeia; mais nascem se você conjurar fogo. Altura +2.",
    description: "Três fachos de fogo levemente brilhantes flutuam ao redor de sua cabeça, dançando junto com seus movimentos. Depois que você causa dano a uma criatura com um Golpe, um dos fogos-fátuos avança em direção a essa criatura, destruindo o fogo-fátuo e causando 1d4 dano de fogo. Se você Conjurar uma Magia com o traço de fogo enquanto tiver menos de três fogos-fátuos, um novo fogo-fátuo aparecerá.\n\n**Altura (+2)** O dano aumenta em 1d4.",
