    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Plantas brotam e atrapalham o movimento na área.",
    description: "Plantas e fungos explodem ou crescem rapidamente, enredando criaturas. Todas as superfícies da área são de terreno difícil. Cada rodada que uma criatura inicia seu turno na área, ela deve tentar uma salvaguarda de Reflexos. Falha: leva –3 m de coincidência de circunstância em suas Velocidades até sair da área, e em uma falha crítica, também fica imóvel por 1 rodada. As criaturas podem tentar Escapar para remover esses efeitos.",
