    summary: "Bolha de líquido viscoso que pega fogo. Altura +2.",
    description: "Você envia uma bolha de líquido viscoso que se transforma em chama. Faça uma rolagem de ataque de magia contra o CA do alvo, causando 1d8 dano de fogo e 1d8 dano persistente de fogo no acerto. O alvo fica enfraquecido 1 até se recuperar do dano persistente de fogo.\n\n**Altura (+2)** O dano inicial e persistente de fogo aumenta em 1d8.",
