    summary: "Mão de ácido move e fere inimigos. Altura +2.",
    description: "Uma mão efêmera com garras agarra o alvo, queimando-o com ácido mágico. O alvo recebe 2d8 dano de ácido mais 1d6 dano persistente de ácido dependendo de sua salvaguarda de Reflexos. Uma criatura que receba dano persistente desta magia sofre -3 m de status em suas Velocidades.\n\n**Sucesso crítico** A criatura não é afetada.\n\n**Sucesso** A criatura sofre metade do dano e nenhum dano persistente, e a garra a move até 1,5 m na direção de sua escolha.\n\n**Falha** A criatura sofre dano total e dano persistente, e a garra a move até 3 m na direção de sua escolha.\n\n**Falha crítica** A criatura sofre dano duplo e dano total persistente, e a garra a move até 6 m na direção de sua escolha.\n\n**Altura (+2)** O dano inicial aumenta em 2d8, e o dano persistente de ácido aumenta em 1d6.",
