    name: "Impulso Caridoso",
    originalName: "Charitable Urge",
    rank: 2,
    traditions: ["arcane", "divine", "occult"],
    traits: ["Concentrate", "Incapacitation", "Manipulate", "Mental"],
    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Força uma criatura a entregar um objeto.",
    description: "Você fala sobre a virtude da caridade, obrigando o alvo a doar seus bens. O alvo deve tentar uma salvaguarda de Vontade. Se o alvo não tiver nenhum item consigo, a magia falha.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** O alvo é atordoado 1 enquanto luta contra o desejo.\n\n**Falha** No seu próximo turno, antes de fazer qualquer outra coisa, o alvo deve apresentar à criatura mais próxima um item em sua posse; o alvo escolhe qual item dar, e se o único item que ele possui for aquele que ele está usando atualmente para se defender, como uma arma durante um encontro de combate, ele pode escolher ficar atordoado por 1 rodada em vez de desistir do item. Isso pode exigir que o alvo do Interagir recupere um item ou se mova para alcançar a criatura mais próxima, e passar o item requer uma ação Interagir normalmente.\n\n**Falha crítica** Como falha, exceto que a duração é de 4 rodadas, e o alvo deve repetir os efeitos de uma falha em cada um de seus turnos. No final de cada um de seus turnos, o alvo pode tentar uma nova salvaguarda de Vontade para reduzir a duração restante em 1 rodada, encerrando os efeitos inteiramente com um sucesso crítico.",
    duration: "varia",
