    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Deixa uma mensagem ilusória para disparar depois. Altura 4º, 6º.",
    description: "Você especifica um gatilho e uma mensagem com até 25 palavras. Quando o gatilho especificado ocorre dentro de 9 m do alvo, o texto ilusório da sua mensagem circula o alvo acompanhado por uma voz desencarnada. Você pode escolher um idioma que conhece para o texto e a fala e como a voz soa. Assim que a mensagem for concluída, a magia termina.\n\n**Altura (4º)** Você pode adicionar um componente sensorial simples para enfatizar a mensagem, como um odor, efeito visual ou sensação física. Esta adição é obviamente ilusória e faz parte da mensagem, durando apenas enquanto a mensagem está sendo lida.\n\n**Altura (6º)** Como 4º grau, mas você pode escolher quantas vezes a magia repete a mensagem antes de terminar; não há limite para o número de repetições.",
