    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "O inimigo é tomado de arrependimento se ferir outros. Altura +2.",
    description: "O arrependimento corrói a mente do alvo, punindo-o por sua violência até que o alvo cesse sua hostilidade. O alvo deve tentar uma salvaguarda de Vontade.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** No final do próximo turno, o alvo sofre 1d8 dano mental por criatura diferente que ele causou dano intencionalmente naquele turno (1d8 se causou dano a uma criatura, 2d8 se causou dano a duas criaturas diferentes e assim por diante). O máximo é 4d8 se danificar quatro ou mais criaturas diferentes.\n\n**Falha** Como sucesso, exceto que a maldição causa dano ao alvo no final de cada turno e dura até que o alvo passe uma rodada completa sem causar dano intencional a outra criatura.\n\n**Falha crítica** Como sucesso, exceto que a maldição causa dano ao alvo no final de cada um de seus turnos e dura até que o alvo passe 24 horas expiando seus pecados percebidos.\n\n**Altura (+2)** A quantidade de dano mental que o alvo sofre para cada criatura que ele causou dano naquele turno aumenta em 1d8, e o dano máximo que o alvo pode receber por turno aumenta em 4d8.",
