    summary: "Luz ofuscante contra invisibilidade e ocultação.",
    description: "Uma onda de luz mágica inunda a área. Você escolhe a aparência da luz, como chamas coloridas e sem calor ou partículas brilhantes. Uma criatura afetada pela luz reveladora é ofuscada. Se a criatura era invisível, ela se torna oculta. Se a criatura já estava oculta por qualquer outro motivo, ela não estará mais oculta.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** A luz afeta a criatura por 2 rodadas.\n\n**Falha** A luz afeta a criatura por 1 minuto.\n\n**Falha crítica** A luz afeta a criatura por 10 minutos.",
