    provenance: { type: 'official' },
    actionType: "two",
    summary: "Deixa invisível o conteúdo de um recipiente (o recipiente continua visível). Altura 4º.",
    description: "Você torna cada item dentro do contêiner invisível, embora o próprio contêiner permaneça visível. Os itens dentro dela são indetectados para todas as criaturas, embora uma criatura possa tentar encontrar um item enfiando a mão na bolsa, tornando um item escondido para ela se tiver sucesso. Além disso, a magia não impede que os itens façam saliências na bolsa, adicionem peso, façam barulho ao serem empurrados e assim por diante. No entanto, a magia evita que qualquer coisa dentro do recipiente caia se for virado. Qualquer objeto removido do contêiner torna-se visível e permanece visível mesmo se for devolvido ao contêiner.\n\n**Altura (4º)** A duração é até a próxima vez que você fizer seus preparativos diários.",
