    description: "Ao Conjurar esta Magia, role 1d10 e anote o resultado; este é o seu número da sorte durante o período. Você ganha a seguinte reação. Depois de usar a reação, a magia termina e você fica temporariamente imune a _Número da Sorte_ até a próxima vez que fizer seus preparativos diários.\n\n**Esse é o meu número!** **reação** (fortuna) **Gatilho** Você rola seu número da sorte como resultado do d20 em uma rolagem de ataque, salvaguardas ou teste de perícia não secreta; **Efeito** Você invoca a fortuna armazenada em seu número da sorte e rola novamente o teste de ativação. No entanto, abusar da sorte tem um preço: se o seu resultado na nova jogada for o mesmo número novamente, você falha criticamente, independentemente do grau de sucesso que normalmente teria obtido.",
