    description: "Você nivela o terreno e afasta obstáculos baixos. Terreno não mágico difícil ou maior difícil terreno composto de terra, entulho, areia e similares na área torna-se terreno normal. Você também pode tentar um teste de contraposição contra terreno mágico difícil e terreno maior difícil composto de materiais terrosos na área, tornando-o terreno normal enquanto durar, se tiver sucesso. O terreno não muda rápido o suficiente para fazer com que alguém perca o equilíbrio, e não elimina recursos de ocultação o suficiente para torná-los não-ocultadores. A critério do Mestre, se você usar esta magia em um “solo” que não tenha uma superfície subjacente para achatar e limpar, como o gelo na superfície de um lago, a magia falhará.\n\n**Altura (4º)** A área aumenta para uma linha de 36 m ao longo do terreno.\n\n**Altura (6º)** A área aumenta para uma linha de 150 m ao longo do terreno.",
