    description: "Conjurando uma intrincada trama de magia protetora, você cria um amortecedor no elo entre você e seu eidolon, permitindo que seu aliado sacrificado sacrifique sua existência para salvá-lo em um momento de necessidade. Você ganha a seguinte reação; depois de usá-lo, a magia termina.\n**Cortar Conduíte** **reação** (concentrar) **Trigger** Seu eidolon sofre dano que o levaria a 0 PV e vem de um efeito diferente de morte; **Efeito** Você rapidamente extingue o vínculo com seu eidolon, fazendo com que seu aliado vinculado desapareça antes que você possa ser abatido. Seu eidolon não se manifesta e você não pode manifestar seu Eidolon por 1 minuto. Em troca, você não sofre o dano desencadeado, embora seu eidolon ainda sofra quaisquer outros efeitos adversos que acompanharam o dano.",
