    provenance: { type: 'official' },
    actionType: "two",
    summary: "Cobre um item com o metal que escolher. Altura +1.",
    description: "Você troca brevemente a superfície externa do metal de um objeto por uma quantidade adequada de um metal precioso comum do Plano do Metal. Em vez disso, você pode escolher um metal incomum ou raro se tiver acesso a ele ou se o Mestre tiver lhe dado acesso a ele.\n\n O objeto funciona como um item daquele metal, desde que o item seja de 2º nível ou inferior. Por exemplo, você poderia transformar uma adaga em uma adaga de ferro frio ou de prata (itens de nível 2º), mas não poderia transformar uma placa completa em uma armadura de ferro frio ou armadura de prata (itens de nível 5º). Isso confere quaisquer propriedades especiais do metal precioso – uma arma revestida de ferro frio ativa fraquezas ao ferro frio, por exemplo – e suprime quaisquer propriedades especiais do metal original do qual o item foi feito.\n\n A magia não altera a integridade estrutural do item nem o danifica. O objeto pode passar por uma inspeção superficial, mas o efeito mágico é óbvio para qualquer um que o estude de perto, portanto não altera o preço do item se você tentar vendê-lo.\n\n**Altura (+1)** O nível máximo do metal precioso aumenta em 2.",
