    summary: "Arremessa estilhaços afiados em um ou mais inimigos. Altura +2.",
    description: "Você lança uma saraivada de estilhaços contra seus inimigos. Faça uma rolagem de ataque de magia contra uma única criatura. Com um acerto, os lascas causam 4d6 dano perfurante. As lascas causam o dobro de dano em um acerto crítico e 1 dano persistente de sangramento. Você pode gastar uma terceira ação enquanto lança esta magia para disparar lascas em dois alvos diferentes em vez de um. Cada um desses ataques aumenta seu julgamento de ataques múltiplos, mas você não aumenta seu ataque de ataques múltiplos até depois de fazer ambos rolagem de ataque de magias por _Saraivada de Estilhaços_.\n\n**Altura (+2)** Aumenta o dano causado a cada alvo em 4d6 e o dano persistente de sangramento em 1.",
