    provenance: { type: 'official' },
    actionType: "two",
    summary: "Faz o eidolom parecer seu gêmeo idêntico (cosmético). Altura 4º.",
    description: "Ninguém te entende mais do que seu eidolon e vice-versa. Usando esse entendimento inato, você transforma seu eidolon em seu gêmeo idêntico, permitindo que ele esconda sua presença ou se faça passar por você até certo ponto. Supondo que você seja um humanóide, o eidolon ganha a característica humanóide além de suas outras características enquanto estiver nesta forma, bem como qualquer outra característica relacionada à sua forma (como elfo ou gnomo). Seu eidolon ganha +4 de bônus de status em testes de Enganação para se passar por você e pode adicionar seu nível a tais testes mesmo se não for treinado.\n\nEmbora seu eidolon se pareça com você, ele não ganha nenhuma habilidade nova e suas estatísticas não mudam de forma alguma – a transformação é puramente cosmética. Se esta transformação reduzir o tamanho do seu eidolon, o eidolon perde quaisquer outros efeitos de seu tamanho maior, como qualquer aumento a ser alcançado. Seu eidolon ainda pode usar equipamento somente se tiver a característica eidolon, que permite que os eidolons o usem. Se necessário, quaisquer itens eidolon que o eidolon estava usando permanecem ativos, mas mudam de tamanho e forma para refletir o que você está vestindo. Você pode Dispensar esta magia para retornar seu eidolon à sua forma original.\n\n**Altura (4º)** A duração aumenta para 1 hora.",
