    description: "Você invoca um _Servo Fantasmal_ e o incumbe de executar uma tarefa específica repetidamente. Escolha uma instrução básica, como varrer o chão ou pegar todos os objetos do chão e colocá-los em uma lixeira designada. O servo executa a tarefa repetidas vezes durante toda a duração, embora nunca possa deixar a área da magia. O servo não é um lacaio e você não precisa Sustentar o Magia para que ele continue a agir. No entanto, ele age em seu próprio tempo e, portanto, não pode realizar nada de útil durante um encontro, mesmo que o encontro aconteça dentro do alcance da magia. Tarefas que dependem de tempo, discrição ou destreza manual significativa estão condenadas ao fracasso. Por exemplo, um servo encarregado de pegar objetos do chão não discriminará entre lixo, tesouro perdido ou objetos que deveriam estar no chão, como uma ratoeira.",
