    provenance: { type: 'official' },
    actionType: "three",
    summary: "Teia que impede o movimento. Altura 4º.",
    description: "Você cria uma teia pegajosa na área que impede o movimento das criaturas. Quadrados preenchidos com teia são terrenos difíceis. Cada vez que uma criatura na teia começa a usar uma ação de movimento ou entra na teia durante uma ação de movimento que está usando, ela deve tentar um teste de Atletismo ou salvaguarda de Reflexos contra seu CD de magia para evitar sofrer um ataque de circunstância às suas Velocidades ou se tornar imóvel. Uma criatura que sai da teia deixa de sofrer um acaso de circunstância para seu Deslocamento da teia.\n\n Cada quadrado pode ser limpo da teia por um único ataque ou efeito que cause pelo menos 5 dano cortante ou 1 dano de fogo. Um quadrado tem CA 5 e falha automaticamente em suas salvaguardas.\n\n**Sucesso crítico** A criatura não é afetada e não precisa tentar mais verificações ou salvaguardas do Atletismo contra a teia neste turno. Se utilizou um teste de Atletismo, ele limpa a teia de cada quadrado que sai durante seu movimento.\n\n**Sucesso** A criatura não é afetada durante sua ação. Se utilizou um teste de Atletismo, ele limpa a teia de cada quadrado que sai durante seu movimento.\n\n**Falha** A criatura sofre –3 m de circunstâncias ocasionais em suas Velocidades até o início de seu próximo turno.\n\n**Falha crítica** A criatura fica imóvel até o início de seu próximo turno, após o qual ela leva –3 m de conveniência às suas Velocidades por 1 rodada. Pode tentar Escapar retirar sua condição de imóvel.\n\n**Altura (4º)** A área da magia aumenta para uma explosão de 6 m, e seu alcance aumenta para 18 m.",
