    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Funde um objeto à mão da criatura; ela não consegue largá-lo. Altura +2.",
    description: "Um objeto segurado por uma criatura se funde à mão daquela criatura e não pode ser largado. Para Desarmar ou Roubar o item, o resultado do teste de perícia deve exceder a CD da magia ou a CD normal, o que for maior. Para largar a arma voluntariamente, o alvo deve gastar uma ação Interagir em vez de uma ação livre, e então ter sucesso em uma salvaguarda de Reflexos; o alvo também deve tentar uma salvaguarda de Reflexos para Interagir para guardar ou trocar o objeto. Se falhar, a ação é desperdiçada, mas se tiver sucesso, eles deixam cair o item e a magia termina. Uma incriatura interessada deve tentar uma salvaguarda inicial de Reflexos contra _Travar Item_. Uma criatura interessada pode optar por falhar criticamente nas salvaguardas.\n\n**Sucesso crítico** A criatura não é afetada.\n\n**Sucesso** A criatura é afetada por 1 rodada.\n\n**Falha** A criatura é afetada por 4 rodadas.\n\n**Falha crítica** A criatura é afetada por 1 minuto.\n\n**Altura (+2)** Você pode escolher um objeto adicional segurado pela mesma criatura ou um objeto adicional segurado por uma criatura adicional.",
