    summary: "A camada superior da pele se desprende sem dano enquanto nova pele cresce.",
    description: "Você remove continuamente e inofensivamente a camada superior da pele enquanto a nova pele se regenera imediatamente, removendo rapidamente as substâncias prejudiciais do corpo. O teste simples para remover dano persistente de efeitos que cobrem sua pele (como a maioria dos danos persistentes de ácido) é reduzido para 5, e você ganha +2 de bônus de status em seu salvamento inicial contra veneno de contato (mas não em salvamentos posteriores, já que, a essa altura, a toxina já entrou em seu sistema). Se você for afetado por um efeito diferente de dano persistente que depende do contato contínuo com sua pele, e se esse efeito permitir uma salvaguardas, você receberá novas salvaguardas contra esse efeito no final de cada turno quando tentar seu teste simples contra dano persistente, e também receberá +2 bônus de status para essas salvaguardas.\n\nEmbora afetado por esta magia, sua pele continuamente trocada torna você muito mais fácil de Rastrear. Qualquer pessoa que esteja rastreando você ganha +2 de bônus de circunstância para fazê-lo, e você não pode ocultar seus rastros.",
