    description: "Seu olhar atravessa ilusões e encontra criaturas e espíritos invisíveis. Você pode ver criaturas invisíveis como se não fossem invisíveis, embora suas características estejam borradas, tornando-as ocultas e difíceis de identificar. Você também pode ver criaturas incorpóreas, como fantasmas, passando por um objeto a até 3 m da superfície de um objeto como formas borradas vistas através desses objetos. Pistas mais sutis também concedem a você um bônus de status de +2 em testes para descrer de ilusões.\n\n**Altura (5º)** Este magia tem duração de 8 horas.",
