    provenance: { type: 'official' },
    actionType: "two",
    summary: "Vermes irrompem em cone da sua boca. Altura +1.",
    description: "Você arrota um enxame de vermes mágicos. Você evoca e molda as criaturas a partir de sua própria imaginação, permitindo alterar a aparência das criaturas (normalmente uma mistura de centopéias, baratas, vespas e vermes), mas isso não altera o efeito da magia. Os vermes atacam qualquer pessoa na área, suas mordidas e picadas causam 2d8 dano perfurante (salvaguarda básica de Reflexos). Uma criatura que falhar em suas salvaguardas também se torna enjoado 1. Quando a magia termina, o enxame desaparece.\n\n**Altura (+1)** O dano aumenta em 1d8.",
