    rank: 2,
    traditions: ["arcane", "occult", "primal"],
    traits: ["Air", "Concentrate", "Manipulate"],
    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Sussurra uma mensagem bem longe. Altura 4º.",
    description: "Você sussurra uma mensagem secreta ou um som ao vento, que o leva até um local designado. A mensagem viaja para uma explosão específica de 3 m dentro do alcance que você conhece, desde que haja um caminho para o vento seguir entre você e a área. A brisa suave passa quase despercebida até chegar ao seu destino, onde transmite sua mensagem silenciosamente. A mensagem é entregue independentemente de quem ou o que está presente para ouvi-la, mesmo que ninguém a receba. Assim que a mensagem for entregue, a magia termina.\n\n Sua mensagem não pode conter mais de 25 palavras, 1 rodada de outros sons ou um simples farfalhar no ar no local de destino. Ele se move a uma velocidade de sua escolha entre 1 milha por hora e 1 milha a cada 10 minutos; quando chega, o vento gira pela área e sussurra a mensagem completa. Um _voice on the breeze_ não pode ativar efeitos mágicos acionados por vozes.\n\n**Altura (4º)** O alcance aumenta para 1.600 quilômetros e a mensagem pode conter até 100 palavras.",
    targets: "explosão de 3 m",
