    rank: 3,
    traditions: ["arcane", "divine", "occult"],
    traits: ["Concentrate", "Emotion", "Manipulate", "Mental"],
    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Força o alvo a aplaudir e torcer por você. Altura 6º.",
    description: "Seu floreio extravagante evoca sentimentos tão poderosos em seu público que você provoca gritos e aplausos. O alvo desta magia deve ser capaz de ver, ouvir ou compreender você de alguma outra forma. O alvo deve tentar uma salvaguarda de Vontade.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** O alvo fica levemente distraído e aplaude enquanto não está totalmente ocupado. Não pode usar reações.\n\n**Falha** O alvo aplaude você tão vigorosamente que não consegue usar reações e fica lento 1. O aplauso é tão envolvente que tem o traço de manipulação. Isso desencadeia reações baseadas na característica manipulação no início do turno do alvo.\n\n**Falha crítica** Como fracasso, mais o alvo fica tão distraído com seus vigorosos aplausos a você que fica fascinado por você.\n\n**Altura (6º)** Você pode mirar em até 10 criaturas.",
