    rarity: "common",
    provenance: { type: 'official' },
    actionType: "three",
    summary: "Faz a superfície ondular. Altura 5º, 7º, 9º.",
    description: "Você faz com que a superfície se levante. A área se torna um terreno difícil e quaisquer rastros na área são destruídos pelo solo agitado. As criaturas que estão na área recebem -1 de status em testes de Acrobacia para Equilíbrio e Rolamento e testes de Atletismo para Salto em Altura e Salto em Distância. Na primeira vez em cada rodada que você Sustentar o Magia, você pode mover a área de agitação até 6 m em qualquer direção. As criaturas imóveis pela magia são carregadas junto com a areia movediça na mesma direção, se possível. As criaturas que entram ou iniciam seu turno na areia movediça devem tentar uma salvaguarda de Reflexos.\n\n**Sucesso crítico** A criatura não é afetada e ignora o terreno difícil da área e pena de teste de perícias até o final do seu turno.\n\n**Sucesso** A criatura ignora a penalidade da área de teste de perícias até o final do seu turno.\n\n**Falha** A criatura é afetada normalmente pelo magia neste turno.\n\n**Falha crítica** A criatura torna-se imóvel dentro da área da magia até escapar. Se a criatura já foi imóvel por areia movediça, ela também cai caída.\n\n**Altura (5º)** O sorte de status aumenta para –2, e o alcance da magia aumenta para 18 m.\n\n**Altura (7º)** O dano de status aumenta para –3, o alcance da magia aumenta para 18 m, e a área da magia aumenta para uma explosão de 9 m.\n\n**Altura (9º)** O dano de status aumenta para –4, o alcance da magia aumenta para 18 m, e a área da magia aumenta para uma explosão de 12 m",
