    provenance: { type: 'official' },
    actionType: "two",
    summary: "Bomba com doença de pele rápida que atinge os inimigos.",
    description: "Você lança uma pequena bomba encantada com uma doença de pele de ação rápida em seus inimigos, fazendo com que sua pele se desenvolva em horríveis feridas sangrentas. Todas as criaturas na área da explosão devem tentar uma salvaguarda de Fortitude.\n\n**Sucesso crítico** A criatura não é afetada e é imune à varíola por 1 semana.\n\n**Sucesso** A criatura é enjoada 2.\n\n**Falha** A criatura sofre de varíola no estágio 1.\n\n**Falha crítica** A criatura sofre de varíola no estágio 2.\n\n**Blister Pox** (doença) **Nível** 5; Uma criatura não pode reduzir seu valor de enjoado abaixo de 1 enquanto estiver sofrendo dano persistente de sangramento de varíola; **Etapa 1** enjoado 2 (1 rodada); **Estágio 2** enjoado 2 e 1d6 dano persistente de sangramento (1 rodada); **Estágio 3** enjoado 2 e 2d6 dano persistente de sangramento (1 rodada); **Estágio 4** enjoado 3 e 2d6 dano persistente de sangramento (1 dia)",
