    traits: ["Concentrate", "Manipulate", "Plant", "Wood"],
    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Faz brotar plantas aquáticas para andar sobre a água. Altura 4º, 6º.",
    description: "Lótus, nenúfares e outras plantas aquáticas florescem a seus pés, permitindo que você caminhe na superfície da água e de outros líquidos. Você pode ir debaixo d'água se desejar, mas nesse caso você deve nadar normalmente. Ao Avançar ou Passo na água, você deixa um rastro de nenúfares enormes, folhas de lótus ou respingos que preenchem as superfícies dos quadrados em seu rastro. Cada quadrado desta trilha pode suportar o peso de 1 criatura Média e dura até o fim do seu próximo turno. Você pode dispensar esta magia mais cedo.\n\n**Altura (4º)** A duração desta magia aumenta para 10 minutos. A trilha dura até a magia terminar ou você Dispensar a magia em você, o que ocorrer primeiro.\n\n**Altura (6º)** A duração aumenta para 1 hora. Seu rastro é permanente mesmo se você Dispensar a magia sobre você, embora se a água não puder sustentar tais plantas, elas morrerão em uma semana. A trilha pode ser removida por _Dissipar Magia_ ou uma magia semelhante.",
