    description: "Você amaldiçoa o alvo com uma sede que nenhuma bebida pode saciar. Você pode descartar a magia. O alvo deve tentar uma salvaguarda de Fortitude.\n\n**Sucesso crítico** A criatura não é afetada e fica temporariamente imune por 1 hora.\n\n**Sucesso** A criatura fica fatigada por 1 rodada.\n\n**Falha** A criatura é imediatamente acometida pela sede, como se não bebesse há dias. Ele fica cansado e sofre 1d4 de dano a cada hora que não pode ser curado até saciar sua sede. Nenhuma quantidade de bebida pode saciar a sede da criatura durante a duração da magia.\n\n**Falha crítica** Como falha, mas a criatura sofre 2d4 de dano a cada hora.\n\n**Altura (+3)** A sede se torna mais insuportável, aumentando o dano a cada hora em 1d4, ou em 2d4 em caso de falha crítica.",
