    summary: "Anima um trecho de corda que rasteja até você e açoita. Altura +2.",
    description: "Você faz com que uma seção de corda ou um objeto parecido com uma corda se anime, deslize até seu quadrado e o envolva, envolvendo-o em fibras retorcidas e amarradas.\n\nAo lançar o Magia e cada vez que Sustentar o Magia, você pode fazer um Golpe corpo a corpo com a corda, que utiliza e contribui para o seu ataque de ataques múltiplos. Esses Golpes de corda são ataques de magia corpo a corpo; ter as características de arma mágica, de alcance e de tropeço; e lidar 3d6 dano cortante.\n\nSe você falhar criticamente em um teste de Derubar usando a corda, você não poderá fazer mais nenhum Golpe com ela neste turno, nem poderá usá-la para fazer um Golpe Reativo até o início do seu próximo turno. Isto substitui os resultados habituais de uma falha crítica em Derubar.\n\n**Altura (+2)** O dano da sua corda Golpes aumenta em 2d6.",
