    actionType: "two",
    summary: "Esquadrão de esqueletos ataca inimigos. Altura +2.",
    description: "Formas esqueléticas disformes irrompem de uma superfície sólida, como um chão de pedra, e preenchem a explosão. A área que preenchem é terreno difícil. Suas garras agarradoras causam 2d6 dano cortante às criaturas no solo na área quando os esqueletos aparecem pela primeira vez com uma salvaguarda básica de Reflexos.\n\n Nas rodadas subsequentes, na primeira vez que você Sustentar o Magia em cada rodada, você pode mover a área dos esqueletos até 6 m dentro do alcance da magia e causar 2d6 dano cortante com uma salvaguarda básica de Reflexos para cada criatura na nova área.\n\n Danificar ou destruir os esqueletos é irrelevante, pois novos ossos surgem do solo para reparar e substituir os que foram destruídos.\n\n**Altura (+2)** O dano aumenta em 1d6.",
