    description: "Um duplo de madeira aparece do nada e leva o golpe em seu lugar. Realize uma ação de Passo. Um bloco de madeira do seu tamanho e com o formato aproximado do seu aparece no espaço que você deixou e absorve o golpe. Este bloco possui Dureza 5 e 20 PV. Se o bloco de madeira for destruído, você sofrerá qualquer dano adicional que o bloco não absorveu. Após receber o golpe, o bloco de madeira desmorona em uma pilha de lascas e poeira.\n\n**Altura (+1)** O PV do bloco aumenta em 10.",
