    description: "Você reduz o alvo para aproximadamente o tamanho de uma moeda com Volume insignificante. Você pode Dispensar a magia, e a magia termina se você jogar o objeto em uma superfície sólida. O objeto não pode ser usado para atacar ou causar danos durante o processo de retorno ao tamanho normal. Se não houver espaço para o objeto retornar ao tamanho normal quando a magia terminar, a duração da magia continua até que o objeto esteja em um local grande o suficiente para acomodar seu tamanho normal.",
