    summary: "Corpo e equipamento de uma criatura viram areia. Altura 5º, 7º.",
    description: "Você concede aspectos de areia ao corpo e equipamento do alvo. O alvo ganha resistência 5 a perfuração e dano cortante, não tem cheiro e não pode sangrar. Em terreno arenoso, mesmo em campo aberto, o alvo tem ocultação suficiente para tentar Esconder-se. Cada vez que o alvo sofrer dano cuja forma de areia conceda resistência, reduza a duração da magia em 1 minuto.\n\n**Altura (5º)** A resistência é 10.\n\n**Altura (7º)** A resistência é 15.",
