    actionType: "two",
    summary: "Cores mutantes ofuscam e fascinam.",
    description: "Você cria uma nuvem de padrões e cores hipnotizantes que paira no ar. As criaturas são ofuscadas enquanto estão dentro da nuvem. Além disso, uma criatura deve tentar uma salvaguarda de Vontade se estiver dentro da nuvem quando você a conjurar, quando entrar na nuvem, quando terminar seu turno dentro da nuvem ou se usar uma ação Procurar ou Interagir na nuvem. Uma criatura atualmente fascinada por _Hipnotizar_ não tenta novos salvamentos.\n\n**Sucesso** O alvo não é afetado.\n\n**Falha** O alvo fica fascinado pela nuvem.\n\n**Falha crítica** O alvo é fascinado pela nuvem. Embora permaneça fascinado, não pode usar reações.",
