    actionType: "two",
    summary: "Você e criaturas próximas ficam invisíveis. Altura 5º.",
    description: "Você e todos os alvos ficam invisíveis, exceto uns para os outros, enquanto os alvos permanecerem dentro da emanação. Se uma criatura tornada invisível por esta magia deixar a área da magia, ela se tornará visível e permanecerá assim mesmo se retornar à área da magia. Se qualquer criatura tornada invisível por esta magia usar uma ação hostil, a magia termina após a ação hostil ser concluída.\n\n**Altura (5º)** Os alvos aumentam para você e até 10 criaturas interessadas. A duração aumenta para 1 hora.",
