    summary: "Erode ou envelhece o alvo artificialmente. Altura +1.",
    description: "Você amaldiçoa o alvo com rápido envelhecimento ou erosão. O efeito depende se o alvo é um objeto, um construto ou uma criatura viva. Artefatos, juntamente com objetos e construções feitas de materiais preciosos (conforme determinado pelo Mestre), são imunes.\n\n- **Objeto** Se o objeto for atendido, seu portador pode tentar uma salvaguarda de Fortitude. Se o portador falhar ou o objeto for abandonado, o objeto imediatamente sofre 4d6 de dano (aplicando Dureza normalmente), e o item é amaldiçoado por uma duração ilimitada. Até que a maldição termine, o item se torna de má qualidade e não pode ser reparado, e a maldição tenta contrapor qualquer magia que restauraria o PV do objeto. _Purificar Aflição_ pode ter como alvo um item afetado por esta magia.\n- **Construct** O constructo sofre 4d6 de dano (salvaguarda básica de Fortitude). Falha: por 1 hora, o construto fica desajeitado 1, está enfraquecido 1 e não pode ser Reparado, e a maldição tenta contrapor qualquer magia que restauraria o PV do construto. Falha crítica: esses efeitos têm duração ilimitada.\n- **Criatura Viva** A criatura viva deve tentar uma salvaguarda de Fortitude. Criaturas eternas são imunes.\n\n**Sucesso crítico** A criatura viva não é afetada.\n\n**Sucesso** A criatura viva envelhece brevemente, tornando-se desajeitado 1 e enfraquecido 1 por 1 rodada.\n\n**Falha** Como sucesso, com duração de 1 hora.\n\n**Falha crítica** Como sucesso, com duração ilimitada.\n\n**Altura (+1)** O dano aumenta em 1d6.",
