    description: "Você cria uma barreira de rajadas de vento que impede qualquer coisa que se mova através dela. A parede dos ventos turbulentos tem 1,5 m de espessura, 18 m de comprimento e 9 m de altura. A parede fica vertical, mas você pode moldar seu caminho. Embora a parede de vento distorça o ar, ela não prejudica a visão. A parede tem os seguintes efeitos.\n Munições de ataques físicos à distância – como flechas, dardos, balas de funda e outros objetos de tamanho semelhante – não podem atravessar a parede. Ataques com armas de longo alcance maiores, como dardos, sofrem -2 por acaso em sua rolagem de ataques se seus caminhos passarem pela parede. Enormes armas de longo alcance e efeitos mágicos que não criam objetos físicos atravessam a parede sem penalidade. A parede é um terreno difícil para criaturas que tentam se mover por terra através dela. Gases, incluindo criaturas em _Forma de Vapor_, não podem passar pela parede. Uma criatura que tentar voar através da parede usando uma ação de movimento deve tentar uma salvaguarda de Fortitude.\n\n**Sucesso crítico** A criatura pode atravessar a parede normalmente neste turno.\n\n**Sucesso** A criatura voadora pode se mover através da parede neste turno, mas a parede é terreno difícil.\n\n**Falha** A parede interrompe o movimento da criatura voadora e qualquer movimento restante de sua ação atual é desperdiçado.\n\n**Falha crítica** Como falha, a criatura é empurrada 3 m para longe da parede.",
