    traditions: ["arcane", "primal"],
    traits: ["Concentrate", "Manipulate", "Water"],
    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Bola de água apaga fogo e pode engolir criaturas.",
    description: "Uma esfera de água com 3 m de diâmetro se forma em um espaço desocupado ao alcance, seja no solo ou na superfície de um líquido. Ao Conjurar esta Magia e cada vez que você Sustentá-la, você pode rolar o orbe, movendo-o até 3 m ao longo do solo ou da superfície de um líquido. O orbe pode se mover pelos espaços de qualquer criatura ou obstáculo que não impeça o fluxo da água. Ele extingue fogos não-mágicos pelos quais se move, de tamanho ou menor, e tenta contrapor quaisquer fogos mágicos pelos quais se move. Se falhar em contrapor um determinado fogo, ele não poderá contrapor esse fogo durante a duração da magia.\n\n O orbe pode engolir criaturas grandes ou menores pelas quais ele se move e pode conter quantas criaturas couberem em seu espaço. O orbe pode tentar engolir a mesma criatura apenas uma vez por turno, mesmo se você o rolar no espaço de uma criatura mais de uma vez. Qualquer criatura Grande ou menor cujo espaço o orbe tente percorrer pode tentar uma salvaguarda de Reflexos.\n\n**Sucesso** A criatura pode deixar o orbe passar (permanecendo em seu espaço ou saindo do caminho do orbe para um espaço de escolha da criatura) ou permitir-se ser empurrada na frente do orbe até o final do movimento do orbe.\n\n**Falha** A criatura é engolfada pelo orbe. Ele se move junto com o orbe e deve prender a respiração ou começar a sufocar (a menos que consiga respirar na água). Uma criatura Média ou menor engolfada e qualquer um que tente afetá-la seguem as regras normais para batalhas aquáticas. Uma criatura grande engolfada geralmente é grande o suficiente para que partes dela se projetem da água e possam sair da água.\n A criatura pode se libertar nadando com um teste bem-sucedido de Atletismo CD 10 ou escapando contra seu CD de magia. Uma criatura libertada sai do espaço do orbe e pode respirar imediatamente.\n\n**Falha crítica** Como falha, mas a criatura não sabe nadar para se libertar.",
    duration: "sustentada até 1 minuto",
    defense: "Reflexos",
    range: "18 m",
