    rarity: "common",
    provenance: { type: 'official' },
    actionType: "three",
    summary: "Deixa uma área segura para atravessar. Altura 5º, 8º.",
    description: "Você torna a passagem segura pela área por um breve período de tempo. Qualquer pessoa que passe pela área ganha os seguintes benefícios contra os efeitos nocivos do terreno e do meio ambiente, incluindo ambientais, terreno perigoso e perigos da área. A magia concede +2 de bônus de status para CA e testes de resistência contra tais efeitos, e resistência 5 a todos os danos causados ​​por tais efeitos. Além disso, a magia evita que qualquer coisa na área que caiu para desabar, como uma ponte frágil ou um teto instável, desmorone, exceto sob tensão extrema que desmoronaria uma estrutura normal desse tipo.\n\n _Passagem Segura_ protege apenas contra danos, não contra inconveniências, e não reduz terreno difícil, remove a condição oculta causada por precipitação, ou algo semelhante, nem protege contra criaturas dentro da área da magia.\n\n**Altura (5º)** A resistência concedida aumenta para 10, e a área pode ter 36 m de extensão.\n\n**Altura (8º)** A resistência concedida aumenta para 15, e a área pode ter 150 m de extensão.",
