    rarity: "common",
    provenance: { type: 'official' },
    actionType: "two",
    summary: "Sensores de vidência em criaturas, que passam a compartilhar a visão.",
    description: "Você coloca um sensor de vidência invisível em cada alvo logo acima de seus olhos. Cada sensor olha para onde o alvo está, e todos os alvos podem vincular sua visão brevemente para ajudar a perceber coisas que um alvo vê, mas os outros não. Cada alvo pode usar uma ação, que possui a característica concentração, para compartilhar o que vê com qualquer número de outros alvos até o início do próximo turno. Apenas uma criatura pode compartilhar sua visão por vez, então se outro alvo realizar esta ação, o efeito termina para qualquer alvo que anteriormente compartilhava sua visão.\n\nIsso melhora o quão bem os destinatários podem perceber qualquer coisa que a criatura que compartilha esteja olhando. Por exemplo, se uma criatura for indetectada por um destinatário, mas observada pela criatura que compartilha, a criatura também será observada pelo destinatário. Normalmente, a criatura é vista como um contorno brilhante sobreposto à sua posição. Isso pode permitir que o destinatário atinja uma criatura que de outra forma não poderia; no entanto, a cobertura e a linha de efeito ainda podem impedir ou impedir a seleção de alvos e os ataques. Isto só pode melhorar a visão do destinatário, e não reduzi-la; por exemplo, se um inimigo fosse indetectado pela criatura partilhadora e observado por um destinatário, o destinatário ainda observaria claramente o inimigo. Quando o compartilhamento da visão termina, o benefício termina.",
