    summary: "Tentáculos de força te ancoram ao chão contra movimento indesejado.",
    description: "Gavinhas de força visíveis ancoram seu corpo ao chão, evitando movimentos indesejados. Sempre que você estiver no chão e uma criatura ou efeito tentar movê-lo à força para fora de seu espaço, você pode usar seu CD de magia no lugar de sua CD de Fortitude como a CD do teste para movê-lo. Se uma criatura normalmente não precisaria de um teste para movê-lo, ela deve ter sucesso em um teste apropriado (geralmente um teste de Atletismo para movimento físico) contra seu CD de magia ou você não será movido; se um efeito normalmente não precisa de um teste para movê-lo, ele deve contrapor gavinhas de reforço ou você não será movido. Quando uma criatura não consegue movê-lo dessa maneira, você pode optar por fazer com que as gavinhas ataquem e empurrem-nas 1,5 m para longe de você.\n\n Embora as gavinhas o ancorem no lugar quando você para, elas se desenraízam facilmente para cooperar com seu próprio movimento voluntário, para que você ainda possa se mover livremente enquanto estiver sob o efeito da magia.",
