    summary: "Abre uma trincheira de terra no terreno solto. Altura +2.",
    description: "Você cava uma trincheira de terra no terreno circundante, que deve ser solo, argila, areia ou outra terra macia, mas não piso ou pedra. A vala tem 1,5 m de largura, 1,5 m de profundidade e até 4,5 m de comprimento. Você pode moldar o caminho da trincheira, mas deve ser uma linha contínua. Você deve conjurar a trincheira em um espaço aberto para que ela não passe por criaturas ou objetos. As criaturas dentro da trincheira têm cobertura contra criaturas fora da trincheira, e criaturas fora da trincheira têm cobertura contra criaturas dentro da trincheira. Criaturas pequenas ou menores na trincheira podem ter maior cobertura contra outras criaturas que não estão perto da borda da trincheira e, por sua vez, essas criaturas podem ter mais cobertura contra criaturas pequenas na trincheira; o GM determina o valor da cobertura adicional, se houver. A entrada ou saída da vala requer um movimento adicional de 1,5 m, mas não requer qualquer tipo de verificação e não é considerado terreno difícil. Ao final da duração da magia, a trincheira desaparece e todas as criaturas na trincheira permanecem em seus espaços em terra firme.\n\n**Altura (+2)** O comprimento máximo da vala aumenta em 4,5 m.",
