    description: "Você invoca uma tartaruga marinha inteligente, que concorda em carregá-lo em seu casco em uma viagem aquática. Esta tartaruga deve ser conjurada em um grande corpo de água dentro do alcance, como um lago ou um rio largo. A tartaruga conjurada é Grande, é capaz de carregar uma criatura Média ou até quatro criaturas Pequenas, e possui Deslocamento de natação de 9 m. A tartaruga não entra em combate e não se coloca intencionalmente em perigo, mas leva você a um destino de sua escolha e segue suas sugestões. A tartaruga funciona como um barco, exceto que ela se controla e não precisa ser pilotada.\n\n**Altura (5º)** O tamanho da tartaruga aumenta para Enorme, tornando-a capaz de carregar uma criatura Grande, até quatro criaturas Médias ou até 16 criaturas Pequenas. Seu Deslocamento de natação aumenta para 12 m, e a duração aumenta para 1 dia.\n\n**Altura (7º)** O tamanho da tartaruga aumenta para Imenso, tornando-a capaz de carregar uma criatura Enorme, até quatro criaturas Grandes, até 16 criaturas Médias ou até 32 criaturas Pequenas. Seu Deslocamento de natação aumenta para 15 m, e a duração aumenta para 1 semana.\n\n**Altura (9º)** O tamanho da tartaruga aumenta para Imenso, tornando-a capaz de carregar duas criaturas Enormes, até oito criaturas Grandes, até 32 criaturas Médias ou até 64 criaturas Pequenas. Seu Deslocamento de natação aumenta para 18 m, e a duração aumenta para 1 mês.",
